  assert(pocket_qjs_program_advance(p, &input, 1));
  assert(host_value(&h, "packaged") == 1 && host_value(&h, "textures") == 0 && host_value(&h, "lastButtons") == 0x41);
  /* A package the profile does not admit fails at create: no guest, no compose. */
  assert(!pocket_qjs_program_boot_package(p, harness_package_rejected, sizeof harness_package_rejected, "harness", "dev.harness", "Harness", 32, 24, 1));
  assert(h.released == 2 && h.composed == 2 && h.initialized == 2 && !pocket_qjs_program_runtime(p));
